def solve(data):
    nums = data['nums']
    current_max = nums[0]
    global_max = nums[0]
    for num in nums[1:]:
        current_max = max(num, current_max + num)
        if current_max > global_max:
            global_max = current_max
    return global_max

def solve(data):
    nums = data['nums']
    current = nums[0]
    max_sum = nums[0]
    for num in nums[1:]:
        current = max(num, current + num)
        if current > max_sum:
            max_sum = current
    return max_sum
